module apb_sram #(
  parameter  int DEPTH = 1024,               // 32-bit words
  localparam int AW    = $clog2(DEPTH)
) (
  input  logic        pclk, presetn,
  input  logic        psel, penable, pwrite,
  input  logic [31:0] paddr,                 // byte address
  input  logic [31:0] pwdata,
  input  logic [3:0]  pstrb,                 // byte strobes (APB4)
  output logic [31:0] prdata,
  output logic        pready,
  output logic        pslverr
);
  logic [31:0]   mem [DEPTH];
  logic [AW-1:0] widx;
  logic          setup, access, bad_addr;

  assign widx     = paddr[AW+1:2];           // byte address -> word index
  assign setup    = psel && !penable;        // 1st cycle of a transfer
  assign access   = psel &&  penable;        // 2nd cycle of a transfer
  assign bad_addr = (paddr[31:AW+2] != '0);  // outside this memory

  // read: start the SRAM read in the setup phase,
  // so the data is ready in the access phase (no wait state)
  always_ff @(posedge pclk)
    if (setup && !pwrite) prdata <= mem[widx];

  // write: in the access phase, only the bytes enabled by pstrb
  always_ff @(posedge pclk)
    if (access && pwrite && !bad_addr) begin
      if (pstrb[0]) mem[widx][ 7: 0] <= pwdata[ 7: 0];
      if (pstrb[1]) mem[widx][15: 8] <= pwdata[15: 8];
      if (pstrb[2]) mem[widx][23:16] <= pwdata[23:16];
      if (pstrb[3]) mem[widx][31:24] <= pwdata[31:24];
    end

  assign pready  = 1'b1;                     // always ready: zero wait states
  assign pslverr = access && bad_addr;
endmodule
